"use client";
import { useId, useRef, useState, type ReactNode } from "react";
import { Icon } from "./icon";
import { project } from "./use-drag";
import { haptic } from "./haptics";
import { cn } from "./cn";

export interface DeviceTileProps {
  /** Name of an icon from the icon set. */
  icon: string;
  /** The device's name. */
  name: string;
  /** State line under the name, for example "60% · Living room". */
  detail: ReactNode;
  /** Whether the device is on: the tile glows. */
  on?: boolean;
  /** Needs attention (an unlocked door, for example). */
  warn?: boolean;
  /** 0–100. Draws a level fill from the bottom, like a dimmer. */
  fill?: number;
  /** Replaces the accessible name. Leave it out: then the visible name and state are the name, as "label in name" (WCAG 2.5.3) asks. */
  label?: string;
  /** What the gestures do, read after the name: "Tap to toggle. Hold for more." */
  hint?: string;
  /** Tap: usually toggles the device. */
  onTap: () => void;
  /** Fires after a half-second press. A tap that follows a hold is swallowed. */
  onHold?: () => void;
  /** Shows the chevron that opens the full controls (the tap-free twin of holding). */
  onMore?: () => void;
  /** Screen-reader name for the chevron. Defaults to "More controls for <name>". */
  moreLabel?: string;
  /** Colour the "on" glow (a lamp's own colour). */
  tint?: string;
  /** Seconds per turn: the icon spins (a fan). */
  spin?: number;
  /** Current level 0–100 for drag-to-set. A sideways drag on the tile sets it; the tile fills live and `onDragCommit` fires on release. */
  dragValue?: number;
  /** Called with the chosen level (0 to 100, in steps of 5) when a sideways drag ends. 0 means off. */
  onDragCommit?: (value: number) => void;
  className?: string;
}

const HOLD_MS = 430;

/**
 * Phone device tile. Tap to toggle. Drag sideways to set its main value: it ticks at each quarter, bumps at either end, stretches
 * if you pull past an end, and a flick carries on after you let go. Hold for more controls (or press the chevron): a slight press-in
 * shows the hold is coming, and a firm tap confirms it was recognised.
 */
export function DeviceTile({ icon, name, detail, on, warn, fill, label, onTap, onHold, onMore, moreLabel, tint, spin, dragValue, onDragCommit, className, hint }: DeviceTileProps) {
  const hintId = useId();
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const fired = useRef(false);
  const hintTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [pressing, setPressing] = useState(false); // a hold is on its way: the tile presses in
  const [rb, setRb] = useState(0); // px stretched past an end of the drag (rubber-banding)
  const crossed = useRef(false);
  const stop = () => { if (timer.current) clearTimeout(timer.current); if (hintTimer.current) clearTimeout(hintTimer.current); setPressing(false); };
  const g = useRef<{ x: number; y: number; w: number; base: number; on: boolean } | null>(null);
  const [live, setLive] = useState<number | null>(null);
  const liveRef = useRef<number | null>(null);
  const trail = useRef<{ t: number; v: number }[]>([]); // recent unrounded values, for the speed of the flick at release
  const canDrag = onDragCommit !== undefined && dragValue !== undefined;
  const move = (e: React.PointerEvent<HTMLButtonElement>) => {
    const s = g.current; if (!s) return;
    const dx = e.clientX - s.x, dy = e.clientY - s.y;
    if (!s.on) { if (Math.abs(dx) < 10 || Math.abs(dx) < Math.abs(dy) * 1.5) { if (Math.abs(dy) > 10) g.current = null; return; } s.on = true; stop(); fired.current = true; try { e.currentTarget.setPointerCapture(e.pointerId); } catch {} }
    const free = s.base + (dx / s.w) * 100, raw = Math.min(100, Math.max(0, free));
    const over = free < 0 ? free : free > 100 ? free - 100 : 0;
    setRb(over === 0 ? 0 : Math.sign(over) * (1 - 1 / (Math.abs(over) / 40 + 1)) * 22);
    if (over !== 0 && !crossed.current) haptic("boundary");
    crossed.current = over !== 0;
    const now = performance.now(); trail.current.push({ t: now, v: raw }); while (trail.current.length > 1 && now - trail.current[0].t > 90) trail.current.shift();
    const v = Math.round(raw / 5) * 5;
    if (v !== liveRef.current) { if (over === 0 && (v % 25 === 0 || v === 0 || v === 100)) haptic("detent"); liveRef.current = v; setLive(v); }
  };
  const end = () => {
    stop();
    if (g.current?.on && liveRef.current !== null) {
      // a flick carries on after the finger lifts: land where its speed would take it
      const a = trail.current[0], b = trail.current[trail.current.length - 1];
      const speed = a && b && b.t - a.t > 8 ? ((b.v - a.v) / 100 / (b.t - a.t)) * 1000 : 0; // fractions of the range per second
      const landed = Math.round((Math.min(1, Math.max(0, project((b?.v ?? liveRef.current) / 100, speed))) * 100) / 5) * 5;
      onDragCommit?.(landed);
    }
    trail.current = []; crossed.current = false; setRb(0);
    g.current = null; liveRef.current = null; setLive(null);
  };
  return (
    <div className={cn("dtw", className)} data-slot="device-tile">
      <button className={cn("dt", (on || (live ?? 0) > 0) && "is-on", warn && "warn", tint && "tinted", live !== null && "dragging")} aria-label={label} aria-describedby={hint ? hintId : undefined}
        data-pressing={pressing ? "" : undefined}
        style={({ ...(tint ? { "--tint": tint } : {}), ...(tint || canDrag ? { touchAction: "pan-y" } : {}), ...(rb ? { "--rb": `${rb}px` } : {}) }) as React.CSSProperties}
        onPointerDown={(e) => { fired.current = false; stop(); if (canDrag) g.current = { x: e.clientX, y: e.clientY, w: e.currentTarget.getBoundingClientRect().width, base: dragValue!, on: false }; if (!onHold) return; hintTimer.current = setTimeout(() => setPressing(true), 120); timer.current = setTimeout(() => { fired.current = true; g.current = null; setPressing(false); haptic("hold"); onHold(); }, HOLD_MS); }}
        onPointerMove={canDrag ? move : undefined}
        onPointerUp={end} onPointerCancel={() => { stop(); g.current = null; liveRef.current = null; crossed.current = false; setRb(0); setLive(null); }} onPointerLeave={(e) => { if (!e.currentTarget.hasPointerCapture(e.pointerId)) stop(); }}
        onContextMenu={(e) => e.preventDefault()}
        onClick={(e) => { if (fired.current) { fired.current = false; e.preventDefault(); return; } onTap(); }}>
        {(live ?? fill) !== undefined ? <i className="dfill" style={{ height: `${live ?? fill}%` }} /> : null}
        <span className={cn("dico", !!spin && "spin")} style={spin ? ({ "--spin": `${spin}s` } as React.CSSProperties) : undefined}><Icon n={icon} /></span>
        <span className="dn"><b>{name}</b><small>{detail}</small></span>
      </button>
      {hint ? <span id={hintId} className="sr">{hint}</span> : null}
      {onMore ? <button className="dmore" onClick={onMore} aria-label={moreLabel ?? `More controls for ${name}`}><Icon n="chev" /></button> : null}
    </div>
  );
}

/** Dashed "add" tile that sits at the end of a device grid. */
export function AddTile({ onClick, hint, children, className }: {
  /** Called when the tile is pressed. */
  onClick: () => void;
  /** A small line under the label. */
  hint?: ReactNode;
  children: ReactNode;
  className?: string;
}) {
  return <div className={cn("dtw", className)} data-slot="add-tile"><button type="button" className="dt add" onClick={onClick}><Icon n="plus" />{children}{hint ? <small>{hint}</small> : null}</button></div>;
}

/* DeviceTile and AddTile (phone device tiles). */
/* Specificity note: .dtw is repeated on the .dico overrides so they still beat the generic ".is-on .dico" rule in globals.css, which now loads after this file. */
.dtw{position:relative;min-width:0;display:flex}
.dt{flex:1;width:100%;min-height:116px;border-radius:22px;background:var(--tile);box-shadow:var(--shadow);padding:14px;display:flex;flex-direction:column;justify-content:space-between;gap:10px;position:relative;overflow:hidden;text-align:left;touch-action:manipulation;-webkit-touch-callout:none;-webkit-user-select:none;user-select:none;transition:transform .12s,background .25s}
.dt>*{position:relative;min-width:0}
.dt{overflow-wrap:anywhere}
.dt .dico{background:var(--tile2)}
.dt.is-on{background:var(--glow-soft)}
.dtw .dt.is-on .dico{background:var(--over);color:var(--glow-ink)}
.dt.warn{background:var(--clay-soft)}
.dtw .dt.warn .dico{background:var(--over);color:var(--clay)}
.dt .dn b{display:block;font-weight:650;line-height:1.2;font-size:0.9062rem;padding-right:4px}
.dt .dn small{display:block;margin-top:2px}
.dt>.dfill{position:absolute;left:0;right:0;bottom:0;background:color-mix(in srgb,var(--glow) 30%,transparent);transition:height .12s;pointer-events:none}
.dmore{position:absolute;top:8px;right:8px;width:38px;height:38px;border-radius:50%;display:grid;place-items:center;color:var(--ink2);z-index:2}
.dmore .ic{transform:rotate(90deg)}
@media (max-width:900px){
  .dt.add{background:transparent;box-shadow:none;border:1.5px dashed var(--line);color:var(--ink3);align-items:center;justify-content:center;text-align:center;font-weight:600;font-size:0.8125rem}
}
/* a lit tile reads its detail line in the strong ink: the fill behind it is tinted, and the softer ink would not hold 4.5:1 */
.dt.is-on .dn small{color:var(--ink)}
/* stretched past an end of a drag: it follows with resistance, and springs back when let go */
.dt{translate:var(--rb,0px) 0;transition:transform .12s,background .25s,translate .45s var(--spring)}
.dt.dragging{translate:var(--rb,0px) 0;transition:none}
/* a hold is on its way: the tile presses in a little, so the long press is not a surprise (Apple: hinting) */
.dt[data-pressing]{animation:dt-hint .31s var(--ease-out) forwards}
@keyframes dt-hint{to{transform:scale(.955);filter:brightness(.97)}}
@media (prefers-reduced-motion:reduce){.dt[data-pressing]{animation:none;filter:brightness(.95)}}

"use client";
import { useRef, type PointerEvent } from "react";

/** Where the pointer is, as fractions of the element, *not* clamped: below 0 or above 1 means it is past the edge (for rubber-banding). */
export interface DragRaw { x: number; y: number }

/** How fast the pointer was moving when it lifted, as fractions of the element per second (positive is right and down). */
export interface DragVelocity { vx: number; vy: number }

/**
 * Where something flicked from `pos` (0 to 1) with velocity `vel` (fractions per second) comes to rest. A flick carries on after the
 * finger lifts, the way a scroll view does: the distance is the sum of a decelerating glide. `rate` is how quickly it slows
 * (0.998 glides a long way, 0.99 a short one). The result is not clamped.
 */
export const project = (pos: number, vel: number, rate = 0.99) => pos + ((vel / 1000) * rate) / (1 - rate);

const WINDOW_MS = 90; // velocity is read from the last moments of the drag, not its whole length

/**
 * Pointer-capture drag over an element. `move` gets the pointer as 0 to 1 fractions of the element's box (clamped), and as a fourth
 * argument the same position unclamped (so a control can stretch when pulled past its end);
 * `end` fires on release with the last position and the velocity at the moment of release (use it with `project`
 * to let a flick carry on). Props go on the element itself.
 */
export function useDrag(
  move: (x: number, y: number, el: HTMLElement, raw: DragRaw) => void,
  end?: (x: number, y: number, el: HTMLElement, v: DragVelocity) => void,
) {
  const live = useRef(false);
  const last = useRef<[number, number]>([0, 0]);
  const raw = useRef<DragRaw>({ x: 0, y: 0 });
  const trail = useRef<{ t: number; x: number; y: number }[]>([]);
  const at = (e: PointerEvent<HTMLElement>): [number, number] => {
    const r = e.currentTarget.getBoundingClientRect();
    raw.current = { x: (e.clientX - r.left) / r.width, y: (e.clientY - r.top) / r.height };
    return [Math.min(1, Math.max(0, raw.current.x)), Math.min(1, Math.max(0, raw.current.y))];
  };
  const note = () => {
    const now = performance.now(), [x, y] = last.current;
    trail.current.push({ t: now, x, y });
    while (trail.current.length > 1 && now - trail.current[0].t > WINDOW_MS) trail.current.shift();
  };
  const velocity = (): DragVelocity => {
    const a = trail.current[0], b = trail.current[trail.current.length - 1];
    const dt = a && b ? b.t - a.t : 0;
    return dt > 8 ? { vx: ((b.x - a.x) / dt) * 1000, vy: ((b.y - a.y) / dt) * 1000 } : { vx: 0, vy: 0 };
  };
  return {
    onPointerDown: (e: PointerEvent<HTMLElement>) => { live.current = true; trail.current = []; e.currentTarget.setPointerCapture(e.pointerId); last.current = at(e); note(); move(...last.current, e.currentTarget, raw.current); },
    onPointerMove: (e: PointerEvent<HTMLElement>) => { if (!live.current) return; last.current = at(e); note(); move(...last.current, e.currentTarget, raw.current); },
    onPointerUp: (e: PointerEvent<HTMLElement>) => { if (!live.current) return; live.current = false; end?.(...last.current, e.currentTarget, velocity()); },
    onPointerCancel: () => { live.current = false; },
    "data-base-ui-swipe-ignore": true,
  } as const;
}
